# -*- coding: utf-8 -*-
"""Гараж Вудчипер: экзотическое тяжёлое оружие (таблица и описания книги)."""
from common import *


def build(out):
    P = 'dlc07'
    out.pack(P, 'Гараж Вудчипер', "Woodchipper's Garage")

    def W(name, key, skill, dmg, mag, ammo, hands, conceal, cost, alt, info, rof=1, **kw):
        e = find(P, key, 'item')
        out.add(P, 'weapon', name, cost=cost, Skill=skill, Damage=dmg, Mag=mag, AmmoKind=ammo, Rof=rof, Hands=hands, Concealable=conceal,
                Alt=alt, Info=info, Lib=e['id'], Page=e['page'], **kw)

    LC = 'Оружие крупного калибра'
    W('Разлагающаяся пусковая установка Биотехники', 'РАЗЛАГАЮЩАЯСЯ', LC, '8d6', 1, 'ракета', '2', False, 500, 'Взрывы, разлагаемое',
      'Экзотическая ракетная установка на 1 выстрел. После выстрела действием можно повернуть рукоятку и раздавить ампулу с реактивным ферментом: оружие полностью разлагается за час.')
    W('Тройное удовольствие от БюджетАрмс', 'ТРОЙНОЕ', LC, '8d6', 2, 'ракета', '2', False, 500, 'Взрывы, встроенный подствольный гранатомёт',
      'Экзотическая ракетная установка низкого качества на 2 выстрела со встроенным несъёмным подствольным гранатомётом низкого качества. Несмотря на экзотику, стреляет нестандартными ракетными и гранатными боеприпасами.')
    W('Сигнальная ракетница', 'СИГНАЛЬНАЯ', LC, '6d6', 1, 'граната', '1', False, 100, 'Взрывы, сигнальная ракета',
      'Одноручный экзотический гранатомёт на 1 выстрел; слишком громоздкий для откидного киберимпланта. Кроме гранат стреляет сигнальными ракетами (стр. 351) по таблице дальности гранатомёта: не взрываются и не наносят урона, видны за 3 км, после приземления действуют как обычные сигнальные ракеты.')
    W('Миднайт Армс SDF-45', 'SDF-45', LC, '8d6', 4, 'ракета (бронебойная)', '2', False, 1000, 'Взрывы, двойной спуск',
      'Экзотическая ракетная установка, дальность до 400 м, магазин 4 бронебойные ракеты. Одна атака выпускает две ракеты, но вместо броска навыка ГМ сам решает, куда они попадут (два места в пределах 50 м от цели, не ближе 10 м друг от друга). Уклонение от взрыва — Уклонение СЛ15 (только для цели, способной уклоняться от пуль). Техник не может убрать эту особенность прицеливания.')
    W('Милитех Эгида', 'ЭГИДА', LC, '4d6', 8, 'заряд батареи', '2', False, 1000, 'Выстрел дробью, не особо летальное',
      'Экзотический дробовик низкого качества (Оружие крупного калибра вместо Тактического). Стреляет только «Выстрелом дробью», урон 4d6 вместо 3d6. Вместо боеприпасов тратит один из 8 зарядов самоперезаряжаемой (1 час) батареи. Урон не вызывает критических ранений и не разрушает броню; если урон снизил бы ПЗ цели до 1, цель теряет сознание с 1 ПЗ.')
    W('Милитех Архимед', 'АРХИМЕД', 'Пилотирование', '8d6', 1, 'умная ракета', '2', False, 5000, 'Взрывы, только умные ракеты',
      'Экзотическая ракетная установка отличного качества; стреляет по навыку «Пилотирование» вместо «Оружия крупного калибра». Только умные ракеты, в комплекте одна. Не работает без киберимпланта «Тактический прицел».')
    W('Воздушка кочевников', 'ВОЗДУШКА', 'Тактическое оружие', '—', 1, 'жидкость', '2', False, 1000, 'Выстрел дробью, только жидкие боеприпасы',
      'Воздушная пушка для жидкостей: работает как экзотический дробовик на 1 выстрел, только «Выстрел дробью», вместо урона покрывает жидкостью все поражённые цели (обычно краска или вода). С кислотой (10eb за выстрел) броня покрытой цели снижается на 1 ОС. Яд или биотоксин: 3 флакона на выстрел; цель делает Сопротивление пыткам/наркотикам как при боеприпасах с ядом (стр. 345–346).')
    W('Слезоточивый защитник от погонь', 'СЛЕЗОТОЧИВЫЙ', LC, '—', 3, 'граната', '2', False, 500, 'Только дымовые или слезоточивые боеприпасы',
      'Экзотический гранатомёт отличного качества с магазином на 3 выстрела; стреляет только дымовыми и слезоточивыми боеприпасами.')
    W('Баллистический гарпун от СлэмДэнс', 'ГАРПУН', 'Оружие ближнего боя / Оружие крупного калибра', '4d6', 1, 'гарпун', '2', False, 1000, 'Оружие ближнего боя; стрельба как из лука/арбалета',
      'Двуручное экзотическое очень тяжёлое оружие ближнего боя. Выстреливается из баллистического корпуса по «Оружию крупного калибра» по таблице дальности луков и арбалетов; при выстреле игнорирует половину брони цели. После выстрела используется как экзотическое очень тяжёлое оружие ближнего боя. Вернув гарпун, его действием «перезаряжают» в корпус.')
    W('Тяжёлая винтовка Штернмайера М-02', 'ШТЕРНМАЙЕРА', LC, '5d6', 80, 'патроны М-02 (бронебойные)', '2', False, 1000, 'Уникальные боеприпасы; без автоогня и огня на подавление',
      'Экзотическая штурмовая винтовка по навыку «Оружие крупного калибра»; магазин 80, не умеет вести автоматический огонь и огонь на подавление. Стреляет собственными круглыми бронебойными патронами: 500eb (дорого) за барабан на 80 — единственный тип боеприпасов.')
    W('Карманная ракетница Това', 'КАРМАННАЯ', LC, '8d6', 1, 'ракета', '2', True, 500, 'Смартлинк, уникальные боеприпасы, складная',
      'Экзотическая ракетная установка низкого качества, раскладывается одним нажатием; в разряженном состоянии прячется (сумка, рюкзак).')
    W('Разрывной огнемёт УрбанТек', 'РАЗРЫВНОЙ', LC, '3d6', 4, 'дробь (зажигательные)', '2', False, 1000, 'Выстрел дробью, разрывной выстрел',
      'Экзотический дробовик по «Оружию крупного калибра»; стреляет только зажигательными снарядами. Цели загораются: пока не потратят действие на тушение, в конце хода получают 4 урона прямо в ПЗ; горение не суммируется; критических ранений нет, прицельные выстрелы невозможны. Альтернативный режим: израсходовав остаток боеприпасов из обоймы, можно выстрелить огненным шаром (взрывается как зажигательная граната, таблица дальности гранатомёта), после чего вы сразу начинаете гореть со смертельной интенсивностью.')
